# HEAVYTECH TubeGo 1.1 - instalacao e correcao do atalho
# Desenvolvido por Danilo - HEAVYTECH
# Instala para o usuario atual, sem alterar a politica global de execucao.
$ErrorActionPreference = 'Stop'
try {
    if ([Environment]::OSVersion.Platform -ne [PlatformID]::Win32NT) { throw 'Use Windows 10 ou Windows 11.' }
    $root = Join-Path $env:LOCALAPPDATA 'HEAVYTECH\TubeGo'
    $desktop = [Environment]::GetFolderPath([Environment+SpecialFolder]::Desktop)
    $menuDir = Join-Path ([Environment]::GetFolderPath([Environment+SpecialFolder]::Programs)) 'HEAVYTECH'
    New-Item -ItemType Directory -Path $root, $menuDir -Force | Out-Null
    function Expand-TubeGoFile([string]$encoded,[string]$destination) {
        $data = [Convert]::FromBase64String($encoded)
        $inputStream = New-Object System.IO.MemoryStream(,[byte[]]$data)
        $gzipStream = New-Object System.IO.Compression.GZipStream($inputStream, [System.IO.Compression.CompressionMode]::Decompress)
        $outputStream = [System.IO.File]::Open($destination, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write)
        try { $gzipStream.CopyTo($outputStream) }
        finally { $outputStream.Dispose(); $gzipStream.Dispose(); $inputStream.Dispose() }
    }
    Write-Host 'HEAVYTECH TubeGo | Atualizacao 1.1' -ForegroundColor Cyan
    $appPath = Join-Path $root 'TubeGo.ps1'
    $iconPath = Join-Path $root 'TubeGo.ico'
    $launcherPath = Join-Path $root 'Iniciar_TubeGo.ps1'
    Expand-TubeGoFile '' $appPath
    Expand-TubeGoFile '' $iconPath
    Expand-TubeGoFile '' $launcherPath
    # Certifique-se de que o arquivo foi gravado e nao possui erro de sintaxe.
    $tokens = $null
    $parseErrors = $null
    [void][System.Management.Automation.Language.Parser]::ParseFile($appPath, [ref]$tokens, [ref]$parseErrors)
    if ($parseErrors.Count -gt 0) { throw ('Erro de sintaxe: ' + $parseErrors[0].Message) }
    $powershell = Join-Path $PSHOME 'powershell.exe'
    if (-not (Test-Path -LiteralPath $powershell)) { throw 'Windows PowerShell nao encontrado.' }
    Write-Host 'Verificando a interface antes de criar o atalho...' -ForegroundColor Yellow
    # A inicializacao de teste nao mostra janela nem baixa nada.
    $result = & $powershell -NoLogo -NoProfile -STA -ExecutionPolicy Bypass -File $appPath -SmokeTest 2>&1
    $code = $LASTEXITCODE
    if ($code -ne 0 -or -not (($result | Out-String) -match 'TUBEGO_SMOKE_TEST_OK')) {
        throw ('Teste da interface falhou. Detalhes: ' + ($result | Out-String))
    }
    # O atalho executa PowerShell diretamente, sem depender de VBScript/WScript.
    $wsh = New-Object -ComObject WScript.Shell
    foreach ($shortcutPath in @((Join-Path $desktop 'HEAVYTECH TubeGo.lnk'), (Join-Path $menuDir 'HEAVYTECH TubeGo.lnk'))) {
        $lnk = $wsh.CreateShortcut($shortcutPath)
        $lnk.TargetPath = $powershell
        $lnk.Arguments = '-NoLogo -NoProfile -STA -WindowStyle Hidden -ExecutionPolicy Bypass -File "' + $launcherPath + '"'
        $lnk.WorkingDirectory = $root
        $lnk.Description = 'HEAVYTECH TubeGo - Desenvolvido por Danilo'
        $lnk.IconLocation = '"' + $iconPath + '",0'
        $lnk.Save()
    }
    Write-Host ''
    Write-Host 'Instalado e verificado com sucesso!' -ForegroundColor Green
    Write-Host 'Pode abrir pelo atalho HEAVYTECH TubeGo na Area de Trabalho.'
    Write-Host 'No uso diario, nao e preciso abrir o PowerShell.'
}
catch {
    Write-Host 'Nao foi possivel concluir a instalacao:' -ForegroundColor Red
    Write-Host $_.Exception.Message -ForegroundColor Red
    Write-Host 'Copie a mensagem acima caso precise de ajuda.'
    exit 1
}